/// Outline chess piece icons (Li style), drawn from li_icon_paths.dart
/// (generated by tools/li_icons.py, which also writes docs/li_icons.svg).
library;

import 'dart:typed_data';

import 'package:flutter/material.dart';

import 'li_icon_paths.dart';
import 'li_pawn_shapes.dart';
import 'step_icons.dart' show parseSvgPath;

export 'li_icon_paths.dart' show LiPiece;

/// A piece icon in the current icon colour (e.g. a button's text colour).
class LiIcon extends StatelessWidget {
  const LiIcon(this.piece, {super.key, this.size, this.color});

  final LiPiece piece;
  final double? size;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final theme = IconTheme.of(context);
    final s = size ?? theme.size ?? 24;
    return CustomPaint(
      size: Size.square(s),
      painter: _LiPainter(piece, color ?? theme.color ?? Colors.white),
    );
  }
}

final _cache = <String, Path>{};

class _LiPainter extends CustomPainter {
  _LiPainter(this.piece, this.color);

  final LiPiece piece;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    if (piece == LiPiece.pawn) return _pawn(canvas, size);
    final g = liPieces[piece]!;
    canvas.save();
    canvas.scale(size.shortestSide / 24);
    final stroke = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = liStroke
      ..strokeJoin = StrokeJoin.round
      ..strokeCap = StrokeCap.round;
    for (final d in g.paths) {
      canvas.drawPath(_cache.putIfAbsent(d, () => parseSvgPath(d)), stroke);
    }
    for (final (x, y, r) in g.circles) {
      canvas.drawCircle(Offset(x, y), r, stroke);
    }
    for (final (x, y, r) in g.dots) {
      canvas.drawCircle(Offset(x, y), r, Paint()..color = color);
    }
    canvas.restore();
  }

  /// The author's pawn: filled shapes minus the holes, as one path (path
  /// subtraction works the same on every renderer, unlike a cleared layer).
  void _pawn(Canvas canvas, Size size) {
    canvas.save();
    canvas.scale(size.shortestSide / 24);
    canvas.drawPath(_pawnPath ??= _buildPawn(), Paint()..color = color);
    canvas.restore();
  }

  static Path? _pawnPath;

  static Path _buildPawn() {
    Path? solid, holes;
    for (final s in liPawnShapes) {
      final m = s.m;
      final unit = Path();
      if (s.circle) {
        unit.addOval(Rect.fromCircle(center: Offset.zero, radius: 1));
      } else {
        unit.addRect(const Rect.fromLTRB(-1, -1, 1, 1));
      }
      final shape = unit.transform(Float64List.fromList([m[0], m[1], 0, 0, m[2], m[3], 0, 0, 0, 0, 1, 0, m[4], m[5], 0, 1]));
      if (s.cut) {
        holes = holes == null ? shape : Path.combine(PathOperation.union, holes, shape);
      } else {
        solid = solid == null ? shape : Path.combine(PathOperation.union, solid, shape);
      }
    }
    return holes == null ? solid! : Path.combine(PathOperation.difference, solid!, holes);
  }

  @override
  bool shouldRepaint(_LiPainter old) => old.piece != piece || old.color != color;
}
